import axios from 'axios';
import 'github-markdown-css/github-markdown.css';
import RelatedArticles from '@/components/RelatedArticles.vue';
import NavBar from '@/components/NavBar.vue';
export default {
  name: 'ArticleDetail',
  components: {
    RelatedArticles,
    NavBar
  },
  data() {
    return {
      article: {},
      comments: [],
      commentForm: {
        nickname: '',
        email: '',
        content: '',
        parent_id: null
      },
      currentUser: JSON.parse(localStorage.getItem('user') || '{}'),
      isLiked: false,
      isFavorited: false,
      showActions: false,
      replyPlaceholder: '写下你的评论...',
      errorMsg: '',
      toc: [],
      tocVisible: false,
      readingProgress: 0,
      replyForms: {},
      commentLikes: new Set()
    };
  },
  computed: {
    mainStyle() {
      return {
        maxWidth: '1000px',
        width: '100%',
        margin: '80px auto 20px',
        padding: '0 20px',
        boxSizing: 'border-box'
      };
    },
    isLoggedIn() {
      return !!localStorage.getItem('token');
    },
    canManage() {
      if (!this.isLoggedIn || !this.article.id) return false;
      return this.currentUser.role === 'admin' || this.article.user_id === this.currentUser.id;
    },
    commentsCount() {
      return this.comments.length;
    },
    nestedComments() {
      const roots = this.comments.filter(c => !c.parent_id);
      return roots.map(root => ({
        ...root,
        replies: this.comments.filter(c => c.parent_id === root.id)
      }));
    }
  },
  mounted() {
    this.updateReadingProgress();
    window.addEventListener('scroll', this.updateReadingProgress, {
      passive: true
    });
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.updateReadingProgress);
  },
  watch: {
    // 监听路由变化，重新获取数据
    '$route.params.id': {
      handler: function () {
        this.fetchArticle();
        this.fetchComments();
        if (this.isLoggedIn) {
          this.fetchInteractionStatus();
          this.fetchCommentLikes();
        }
        this.initCommentForm();
      },
      immediate: true
    }
  },
  methods: {
    updateReadingProgress() {
      const scrollTop = window.pageYOffset || document.documentElement.scrollTop || 0;
      const total = (document.documentElement.scrollHeight || 0) - (document.documentElement.clientHeight || 0);
      const progress = total > 0 ? scrollTop / total * 100 : 0;
      this.readingProgress = Math.max(0, Math.min(100, Math.round(progress)));
    },
    buildToc() {
      // 确保有文章数据和html_content
      if (!this.article || !this.article.html_content) {
        this.toc = [];
        return;
      }
      const html = this.article.html_content;

      // 创建临时容器来解析HTML
      const container = document.createElement('div');
      container.innerHTML = html;

      // 查找所有标题元素
      const headings = Array.from(container.querySelectorAll('h1,h2,h3'));
      if (headings.length === 0) {
        this.toc = [];
        return;
      }
      console.log('找到的标题数量:', headings.length);

      // 生成目录数据
      this.toc = headings.map((h, idx) => {
        const level = parseInt(h.tagName.replace('H', ''), 10);
        const text = (h.textContent || '').trim();

        // 生成唯一ID，使用索引确保唯一性
        const id = `heading-${idx}`;
        console.log(`生成目录项: ID=${id}, 文本=${text}, 级别=${level}`);
        return {
          id,
          text,
          level
        };
      }).filter(item => item.text);

      // 确保页面中的标题元素有正确的ID
      this.$nextTick(() => {
        const contentElement = document.querySelector('.content');
        if (contentElement) {
          const contentHeadings = contentElement.querySelectorAll('h1,h2,h3');
          console.log('页面中的标题数量:', contentHeadings.length);
          contentHeadings.forEach((h, idx) => {
            const id = `heading-${idx}`;
            h.setAttribute('id', id);
            console.log(`设置标题ID: ${id} -> ${h.textContent.trim()}`);
          });
        }
      });
    },
    scrollToHeading(id) {
      console.log('点击目录项，尝试跳转到:', id);

      // 尝试直接查找标题元素
      let el = document.getElementById(id);

      // 如果找不到，尝试在内容区域查找
      if (!el) {
        const contentElement = document.querySelector('.content');
        if (contentElement) {
          const headings = contentElement.querySelectorAll('h1,h2,h3');
          console.log('内容区域中的标题数量:', headings.length);

          // 查找匹配的标题
          headings.forEach(heading => {
            const headingId = heading.getAttribute('id');
            console.log('标题ID:', headingId, '标题文本:', heading.textContent.trim());
            if (headingId === id) {
              el = heading;
            }
          });
        }
      }
      if (el) {
        console.log('找到目标元素:', el);
        // 滚动到标题位置，考虑导航栏的高度
        const navbarHeight = 60;
        const elTop = el.getBoundingClientRect().top;
        window.scrollTo({
          top: window.pageYOffset + elTop - navbarHeight - 20,
          behavior: 'smooth'
        });
      } else {
        console.error('未找到目标标题元素:', id);
      }
      this.tocVisible = false;
    },
    initCommentForm() {
      if (this.isLoggedIn) {
        this.commentForm.nickname = this.currentUser.username;
        this.commentForm.email = this.currentUser.email || '';
      }
    },
    onCommentFocus() {
      this.showActions = true;
    },
    handleReply(comment, parentId = null) {
      this.commentForm.parent_id = parentId || comment.id;
      this.commentForm.content = `@${comment.nickname} `;
      this.replyPlaceholder = `回复 @${comment.nickname}`;
      this.showActions = true;
      // 滚动到输入框
      document.querySelector('.comment-form').scrollIntoView({
        behavior: 'smooth'
      });
    },
    cancelReply() {
      this.commentForm.parent_id = null;
      this.commentForm.content = '';
      this.replyPlaceholder = '写下你的评论...';
      this.showActions = false;
    },
    async fetchArticle() {
      try {
        const id = this.$route.params.id;
        if (!id) {
          this.errorMsg = '文章 ID 缺失';
          this.$message.error('文章 ID 缺失');
          return;
        }
        const response = await axios.get(`http://localhost:3000/api/articles/${id}`);
        this.article = response.data;
        this.errorMsg = '';
        this.buildToc();
        this.$nextTick(() => {
          this.updateReadingProgress();
        });
      } catch (error) {
        console.error('获取文章详情失败:', error);
        this.article = {};
        const url = `http://localhost:3000/api/articles/${this.$route.params.id}`;
        this.errorMsg = `获取文章失败: ${error.message} (URL: ${url})`;
        this.$message.error('获取文章详情失败');
        this.toc = [];
      }
    },
    async fetchInteractionStatus() {
      try {
        const response = await axios.get(`http://localhost:3000/api/interactions/status/${this.$route.params.id}`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        this.isLiked = response.data.isLiked;
        this.isFavorited = response.data.isFavorited;
      } catch (error) {
        console.error('获取交互状态失败', error);
      }
    },
    async handleLike() {
      try {
        const response = await axios.post('http://localhost:3000/api/interactions/like', {
          article_id: this.article.id
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        this.isLiked = response.data.isLiked;
        this.$message.success(response.data.message);
        this.fetchArticle(); // 重新获取以更新计数
      } catch (error) {
        this.$message.error('点赞失败');
      }
    },
    async handleFavorite() {
      try {
        const response = await axios.post('http://localhost:3000/api/interactions/favorite', {
          article_id: this.article.id
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        this.isFavorited = response.data.isFavorited;
        this.$message.success(response.data.message);
        this.fetchArticle(); // 重新获取以更新计数
      } catch (error) {
        this.$message.error('收藏失败');
      }
    },
    isCommentLiked(commentId) {
      return this.commentLikes.has(commentId);
    },
    toggleReplyForm(comment, parentId = null) {
      // 直接更新状态，避免延迟
      comment.showReplyForm = !comment.showReplyForm;
      if (comment.showReplyForm) {
        // 直接创建回复表单对象
        this.replyForms = {
          ...this.replyForms,
          [comment.id]: {
            content: '',
            parent_id: parentId || comment.id
          }
        };
      } else {
        // 直接删除回复表单对象
        const newReplyForms = {
          ...this.replyForms
        };
        delete newReplyForms[comment.id];
        this.replyForms = newReplyForms;
      }
    },
    getReplyForm(commentId) {
      if (!this.replyForms[commentId]) {
        // 确保回复表单对象存在
        this.replyForms = {
          ...this.replyForms,
          [commentId]: {
            content: '',
            parent_id: null
          }
        };
      }
      return this.replyForms[commentId];
    },
    async submitReply(comment) {
      const replyForm = this.getReplyForm(comment.id);
      if (!replyForm.content.trim()) {
        this.$message.warning('回复内容不能为空');
        return;
      }
      try {
        const response = await axios.post('http://localhost:3000/api/comments', {
          article_id: this.article.id,
          content: replyForm.content,
          parent_id: replyForm.parent_id,
          nickname: this.currentUser.username,
          email: this.currentUser.email || ''
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        this.$message.success('回复成功');
        this.toggleReplyForm(comment);
        this.fetchComments();
      } catch (error) {
        this.$message.error('回复失败');
      }
    },
    async fetchCommentLikes() {
      if (!this.isLoggedIn) return;
      try {
        const response = await axios.get(`http://localhost:3000/api/comments/likes`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        // 确保正确设置点赞状态
        this.commentLikes.clear();
        if (response.data && response.data.likedCommentIds) {
          response.data.likedCommentIds.forEach(id => {
            this.commentLikes.add(id);
          });
        }
      } catch (error) {
        console.error('获取评论点赞状态失败', error);
        // 出错时清空点赞状态，避免错误显示
        this.commentLikes.clear();
      }
    },
    async handleCommentLike(comment) {
      if (this.isCommentLiked(comment.id)) {
        this.$message.warning('已经点赞过了');
        return;
      }
      try {
        const response = await axios.post(`http://localhost:3000/api/comments/${comment.id}/like`, {}, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });

        // 更新原始comments数组中的评论对象，确保响应式更新
        const originalComment = this.comments.find(c => c.id === comment.id);
        if (originalComment) {
          this.$set(originalComment, 'likes_count', response.data.likes_count);
        }

        // 同时更新传入的评论对象
        this.$set(comment, 'likes_count', response.data.likes_count);

        // 更新点赞状态
        this.commentLikes.add(comment.id);

        // 强制重新渲染嵌套评论
        this.$forceUpdate();
        this.$message.success(response.data.message);
      } catch (error) {
        this.$message.error('点赞失败');
      }
    },
    handleEdit() {
      this.$router.push(`/article/edit/${this.article.id}`);
    },
    async handleDelete() {
      try {
        await this.$confirm('确定要删除这篇文章吗？', '提示', {
          type: 'warning'
        });
        await axios.delete(`http://localhost:3000/api/articles/${this.article.id}`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        this.$message.success('删除成功');
        this.$router.push('/');
      } catch (error) {
        if (error !== 'cancel') this.$message.error('删除失败');
      }
    },
    async fetchComments() {
      try {
        const id = this.$route.params.id;
        const response = await axios.get(`http://localhost:3000/api/comments/article/${id}`);
        // 按创建时间倒序排序，新评论在前
        this.comments = response.data.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
        if (this.isLoggedIn) {
          this.fetchCommentLikes();
        }
      } catch (error) {
        console.error('获取评论失败', error);
      }
    },
    async submitComment() {
      if (!this.commentForm.nickname || !this.commentForm.content) {
        this.$message.warning('请填写昵称和内容');
        return;
      }
      try {
        const headers = {};
        const token = localStorage.getItem('token');
        if (token) {
          headers.Authorization = `Bearer ${token}`;
        }
        await axios.post('http://localhost:3000/api/comments', {
          ...this.commentForm,
          article_id: this.article.id
        }, {
          headers
        });
        this.$message.success('评论成功');
        this.commentForm.content = '';
        this.cancelReply();
        this.fetchComments();
      } catch (error) {
        this.$message.error('评论失败');
      }
    },
    formatDate(dateStr) {
      if (!dateStr || dateStr === 'undefined' || dateStr === 'null') return '未知时间';
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return '无效日期';
      const Y = date.getFullYear();
      const M = (date.getMonth() + 1).toString().padStart(2, '0');
      const D = date.getDate().toString().padStart(2, '0');
      const h = date.getHours().toString().padStart(2, '0');
      const m = date.getMinutes().toString().padStart(2, '0');
      if (isNaN(Y) || isNaN(date.getMonth()) || isNaN(date.getDate())) return '无效日期';
      return `${Y}-${M}-${D} ${h}:${m}`;
    }
  }
};
